-- GENERATED by tools/gamekit/bundle.py from tools/gamekit/gamekit.lua and apps/cryptogram/src/
-- -- edit those files, not this one.
local kit = (function()
-- gamekit: shared pieces for the API 2.9 puzzle games (Lights Out, Peg Solitaire, Nonograms,
-- Knight's Tour). tools/gamekit/bundle.py puts it in front of a game's src/main.lua as
-- `local kit = (function() ... end)()`, since the device has no require for package files.
--
--   kit.W, kit.H                      screen size
--   kit.font(name), kit.width(f, s), kit.line_h(name)
--   kit.short(s, n), kit.drop_last(s), kit.wrap(s, fname, maxw)
--   kit.read(name), kit.write(name, s), kit.kv(s)   ctx.storage helpers ("key=value" lines)
--   kit.now_ms(), kit.refresh()
--   kit.moved()                       count a move (a hook for a periodic full refresh; see below)
--   kit.key_accepted(ev)              side buttons send several events per press: keep one
--   kit.show(m), kit.close(), kit.modal()   a box over the screen: { title, lines, rows, cancel },
--                                     rows = { { {label, fn, enabled}, .. }, .. }
--   kit.draw_modal(gg), kit.tap_modal(x, y) -> true when the box took the tap
--   kit.button(gg, x, y, w, h, label, opts)  a framed button with a centred label
-- Every ctx.* function is a method on this API: colon calls everywhere. Nothing is filled black:
-- large black areas ghost on e-ink, and the host draws text black even when asked for white.

local kit = {}
kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end
function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- drop the last character (a whole UTF-8 sequence)
function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, ROW_H, GAP = 20, 56, 10
local BOX_W = kit.W - 40      -- refreshed in layout(): an app may set kit.W, kit.H for a landscape screen
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  BOX_W = kit.W - 40
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

-- Cryptogram for XTOS Licorice, API 2.0 (uses tools/gamekit).
--
-- A quote a day with every letter swapped for another: work out which letter stands for which.
-- The quotes come from make_data.py (one "author|quote" a line in the package's data section);
-- day N from 1 November 2026 plays line N, and the list starts over after the last one. The
-- day's cipher is made from the day number, so it is the same every time; no letter stands for
-- itself. The author is part of the puzzle (a proverb just says so).
--
-- Tap a letter of the puzzle: every place it appears is framed; tap a key to say what it stands
-- for, and the next empty letter is chosen. A key already used moves from its old place. Hint
-- shows the framed letter (or the first one still open), Check strikes out the wrong guesses,
-- Erase clears the framed letter. Earlier days can be played too; each day's guesses are kept.

local W, H = kit.W, kit.H
local QUOTE_Y, QUOTE_BOTTOM = 100, 566
local CW, RH = 25, 58                     -- cell width, row height
local STATUS_Y = 572
local KEY_Y, KEY_H, KEY_GAP = 600, 44, 6
local BTN_Y, BTN_H = 750, 46
local ALPHA = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'

local today, pday = 0, 0
local puz = nil          -- { no, quote, author, proverb, cipher = {plain -> cipher}, plain = {cipher -> plain}, used = {cipher letters} }
local guess = {}         -- cipher letter -> guessed plain letter
local hinted = {}        -- cipher letter -> true when Hint showed it
local wrong = {}         -- cipher letter -> true when Check struck it out
local checks, solved = 0, false
local cells = {}         -- { x, y, ch, c } (c = cipher letter, nil for punctuation)
local cursor = nil       -- index in cells
local msg = nil
local saved = {}         -- day -> the saved line
local ERR = nil

------------------------------------------------------------------ days

local function days_from_civil(y, m, d)
  y = m <= 2 and y - 1 or y
  local era = (y >= 0 and y or y - 399) // 400
  local yoe = y - era * 400
  local doy = (153 * (m > 2 and m - 3 or m + 9) + 2) // 5 + d - 1
  local doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
  return era * 146097 + doe - 719468
end
local START = days_from_civil(2026, 11, 1)

local function civil(z)
  z = z + 719468
  local era = (z >= 0 and z or z - 146096) // 146097
  local doe = z - era * 146097
  local yoe = (doe - doe // 1460 + doe // 36524 - doe // 146096) // 365
  local doy = doe - (365 * yoe + yoe // 4 - yoe // 100)
  local mp = (5 * doy + 2) // 153
  local d = doy - (153 * mp + 2) // 5 + 1
  local m = mp < 10 and mp + 3 or mp - 9
  return yoe + era * 400 + (m <= 2 and 1 or 0), m, d
end

local MONTHS = { 'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec' }
local WDAYS = { 'Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat' }
local function date_label(day)
  local _y, m, d = civil(day)
  return WDAYS[(day + 4) % 7 + 1] .. ' ' .. d .. ' ' .. MONTHS[m]
end

local function local_day()
  local ok, t = pcall(function() return ctx.clock:now() end)
  if not ok or type(t) ~= 'table' or not tonumber(t.epoch_sec) then return START end
  local e = math.floor(tonumber(t.epoch_sec))
  if tonumber(t.hour) then
    local wall = tonumber(t.hour) * 3600 + (tonumber(t.minute) or 0) * 60 + (tonumber(t.second) or 0)
    local off = (wall - e % 86400) % 86400
    if off > 14 * 3600 then off = off - 86400 end
    off = math.floor(off / 900 + 0.5) * 900
    return (e + off) // 86400
  end
  return e // 86400
end

------------------------------------------------------------------ quotes

local count = nil
local function read_line(n)
  local P = ctx.package
  if not P then return nil end
  local ok, r = pcall(function() return P:open_text('quotes.txt', { max_bytes = 200000, max_line_bytes = 512 }) end)
  if not ok or r == nil or type(r) == 'string' then return nil end
  local line, k = nil, 0
  while true do
    local okl, l = pcall(function() return r:read_line() end)
    if not okl or l == nil then break end
    if l:find('|', 1, true) then
      k = k + 1
      if k == n then line = l; if count then break end end
    end
  end
  pcall(function() r:close() end)
  if not count or k > count then count = math.max(count or 0, k) end
  return line
end

local function puzzle_no(day)
  if not count then read_line(1) end
  if not count or count == 0 then return nil end
  return (day - START) % count + 1
end

-- the day's cipher: a shuffle of the alphabet in which no letter stays in place
local function make_cipher(day)
  local seed = (day * 2654435761) % 2147483648 + 7
  local function rnd(n)
    seed = (seed * 1103515245 + 12345) % 2147483648
    return seed // 65536 % n + 1
  end
  local t = {}
  for k = 1, 26 do t[k] = k end
  for _try = 1, 100 do
    for k = 26, 2, -1 do
      local j = rnd(k)
      t[k], t[j] = t[j], t[k]
    end
    local fixed = false
    for k = 1, 26 do if t[k] == k then fixed = true end end
    if not fixed then break end
  end
  local enc, dec = {}, {}
  for k = 1, 26 do
    local p, c = ALPHA:sub(k, k), ALPHA:sub(t[k], t[k])
    enc[p], dec[c] = c, p
  end
  return enc, dec
end

local function load_puzzle(day)
  local no = puzzle_no(day)
  local line = no and read_line(no)
  if not line then return nil end
  local author, quote = line:match('^([^|]*)|(.*)$')
  local enc, dec = make_cipher(day)
  local p = { no = no, quote = quote:upper(), author = author, proverb = author == 'Proverb', cipher = enc, plain = dec, used = {} }
  local text = p.quote .. (p.proverb and '' or (' ' .. author:upper()))
  for ch in text:gmatch('%u') do p.used[enc[ch]] = true end
  return p
end

------------------------------------------------------------------ layout

local function char_w(ch) return ch:match('%u') and CW or 12 end

local function layout()
  cells = {}
  local maxw = W - 24
  local function place(words, y0)
    local x, y = 12, y0
    for _k, word in ipairs(words) do
      local ww = 0
      for ch in word:gmatch('.') do ww = ww + char_w(ch) end
      if x > 12 and x + ww > 12 + maxw then x, y = 12, y + RH end
      for one in word:gmatch('.') do
        cells[#cells + 1] = { x = x, y = y, ch = one, c = one:match('%u') and puz.cipher[one] or nil }
        x = x + char_w(one)
      end
      x = x + 14
    end
    return y
  end
  local words = {}
  for w in puz.quote:gmatch('%S+') do words[#words + 1] = w end
  local y = place(words, QUOTE_Y)
  puz.author_y = y + RH + 4
  if not puz.proverb then
    local aw = {}
    for w in puz.author:upper():gmatch('%S+') do aw[#aw + 1] = w end
    -- the author's line starts with a dash, so it reads as the author
    cells[#cells + 1] = { x = 12, y = puz.author_y, ch = '-', c = nil }
    local first = #cells + 1
    local last_y = place(aw, puz.author_y)
    for k = first, #cells do cells[k].x = cells[k].x + 20 end
    puz.bottom = last_y + RH
  else
    puz.bottom = puz.author_y + RH
  end
  -- the puzzle sits in the middle of its area
  local shift = math.max(0, (QUOTE_BOTTOM - puz.bottom) // 2)
  for _k, cl in ipairs(cells) do cl.y = cl.y + shift end
  puz.author_y, puz.bottom = puz.author_y + shift, puz.bottom + shift
end

------------------------------------------------------------------ storage

local function state_line()
  local gs, h = {}, {}
  for k = 1, 26 do
    local c = ALPHA:sub(k, k)
    gs[k] = guess[c] or '.'
    h[k] = hinted[c] and '1' or '0'
  end
  return table.concat(gs) .. '\t' .. table.concat(h) .. '\t' .. (solved and 1 or 0) .. '\t' .. checks
end

local function save()
  if puz then saved[pday] = state_line() end
  local days = {}
  for d in pairs(saved) do days[#days + 1] = d end
  table.sort(days)
  local t = {}
  for k = math.max(1, #days - 400), #days do t[#t + 1] = days[k] .. '\t' .. saved[days[k]] end
  kit.write('days.txt', table.concat(t, '\n'))
end

local function load_saved()
  for d, rest in (kit.read('days.txt') or ''):gmatch('(%-?%d+)\t([^\n]*)') do saved[tonumber(d)] = rest end
end

------------------------------------------------------------------ play

local function complete()
  for c in pairs(puz.used) do if not guess[c] then return false end end
  return true
end

local function all_right()
  for c in pairs(puz.used) do if guess[c] ~= puz.plain[c] then return false end end
  return true
end

local function open_day(day)
  local p = load_puzzle(day)
  if not p then ERR = 'no quotes in the package'; return end
  puz, pday = p, day
  guess, hinted, wrong, checks, solved, msg = {}, {}, {}, 0, false, nil
  local s = saved[day]
  if s then
    local gs, h, sv, ck = s:match('^(%S+)\t(%S+)\t(%d)\t(%d+)')
    if gs and #gs == 26 then
      for k = 1, 26 do
        local c = ALPHA:sub(k, k)
        if gs:sub(k, k) ~= '.' then guess[c] = gs:sub(k, k) end
        if h:sub(k, k) == '1' then hinted[c] = true end
      end
      solved, checks = sv == '1', tonumber(ck) or 0
    end
  end
  layout()
  cursor = nil
  for i, cl in ipairs(cells) do if cl.c and not guess[cl.c] then cursor = i; break end end
  if solved then msg = 'Solved!' end
end

local function sel() return cursor and cells[cursor] and cells[cursor].c end

local function next_open(from)
  local n = #cells
  for k = 1, n do
    local i = (from + k - 1) % n + 1
    if cells[i].c and not guess[cells[i].c] then return i end
  end
  return nil
end

local function finish_check()
  if complete() then
    if all_right() then
      solved = true
      local h = 0
      for _c in pairs(hinted) do h = h + 1 end
      msg = 'Solved!  Hints ' .. h .. ', checks ' .. checks
      cursor = nil
    else
      msg = 'Not quite: some letters are wrong. Check marks them.'
    end
  end
end

local function assign(p)
  local c = sel()
  if not c or solved then return end
  if hinted[c] then msg = 'That letter was given by a hint'; return end
  for other, v in pairs(guess) do
    if v == p and other ~= c then
      if hinted[other] then msg = p .. ' is already given by a hint'; return end
      guess[other], wrong[other] = nil, nil
    end
  end
  guess[c], wrong[c] = p, nil
  msg = nil
  cursor = next_open(cursor) or cursor
  finish_check()
  kit.moved()
  save()
end

local function erase()
  local c = sel()
  if not c or solved or hinted[c] then return end
  guess[c], wrong[c] = nil, nil
  msg = nil
  save()
end

local function hint()
  if solved then return end
  local c = sel()
  if not c or guess[c] == puz.plain[c] then
    local i = nil
    for k, cl in ipairs(cells) do if cl.c and guess[cl.c] ~= puz.plain[cl.c] then i = k; break end end
    if not i then return end
    cursor, c = i, cells[i].c
  end
  local p = puz.plain[c]
  for other, v in pairs(guess) do if v == p and other ~= c then guess[other], wrong[other] = nil, nil end end
  guess[c], hinted[c], wrong[c] = p, true, nil
  msg = c .. ' stands for ' .. p
  cursor = next_open(cursor) or cursor
  finish_check()
  save()
end

local function check()
  if solved then return end
  checks = checks + 1
  local n = 0
  for c, v in pairs(guess) do
    if v ~= puz.plain[c] then wrong[c] = true; n = n + 1 end
  end
  msg = n == 0 and 'No wrong letters so far' or (n .. ' wrong letter' .. (n == 1 and '' or 's') .. ' struck out')
  save()
end

------------------------------------------------------------------ drawing

local function times(c)
  local n = 0
  for _k, cl in ipairs(cells) do if cl.c == c then n = n + 1 end end
  return n
end

local function key_rect(k)        -- k from 1 to 26
  local row, col = (k - 1) // 9, (k - 1) % 9
  local kw = (W - 24 - 8 * KEY_GAP) // 9
  local x0 = row == 2 and 12 + (kw + KEY_GAP) // 2 or 12
  return x0 + col * (kw + KEY_GAP), KEY_Y + row * (KEY_H + KEY_GAP), kw, KEY_H
end

local BUTTONS = { 'Hint', 'Check', 'Erase', 'Menu' }
local function button_rect(k)
  local bw = (W - 24 - 3 * 8) // 4
  return 12 + (k - 1) * (bw + 8), BTN_Y, bw, BTN_H
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    gg:text(12, 12, 'Cryptogram', { font = kit.font('large') })
    if puz then
      local h = 0
      for _c in pairs(hinted) do h = h + 1 end
      gg:text(12, 52, kit.short(date_label(pday) .. (pday == today and '' or ' (earlier)') .. '   No. ' .. puz.no ..
        (h > 0 and ('   hints ' .. h) or '') .. (solved and '   solved' or ''), 46), { font = kit.font('small') })
    end
    gg:line(0, 90, W, 90)
    if kit.modal() then kit.draw_modal(gg); return end
    if not puz then return end
    local big, small = kit.font('large'), kit.font('small')
    local s = sel()
    for i, cl in ipairs(cells) do
      if cl.c then
        local gs = guess[cl.c]
        if gs then
          gg:text(cl.x + (CW - kit.width(big, gs)) // 2, cl.y, gs, { font = big })
          if wrong[cl.c] then gg:line(cl.x + 3, cl.y + 26, cl.x + CW - 4, cl.y + 4, { line_width = 2 }) end
        end
        gg:line(cl.x + 2, cl.y + 31, cl.x + CW - 3, cl.y + 31)
        if hinted[cl.c] then gg:line(cl.x + 2, cl.y + 33, cl.x + CW - 3, cl.y + 33) end
        gg:text(cl.x + (CW - kit.width(small, cl.c)) // 2, cl.y + 34, cl.c, { font = small })
        if s and cl.c == s then
          gg:rect(cl.x, cl.y - 4, CW - 1, RH - 2, { line_width = i == cursor and 3 or 1 })
        end
      else
        gg:text(cl.x + (char_w(cl.ch) - kit.width(big, cl.ch)) // 2, cl.y, cl.ch, { font = big })
      end
    end
    if puz.proverb then gg:text(12, puz.author_y, '- Proverb', { font = kit.font('medium') }) end
    local status = msg
    if not status and s then status = s .. ' appears ' .. times(s) .. (times(s) == 1 and ' time' or ' times') .. '. Tap its letter below.' end
    if status then gg:text(12, STATUS_Y, kit.short(status, 46), { font = small }) end
    local usedp = {}
    for cc, v in pairs(guess) do usedp[v] = cc end
    local med = kit.font('medium')
    for k = 1, 26 do
      local l = ALPHA:sub(k, k)
      local x, y, kw, kh = key_rect(k)
      local here = s and guess[s] == l
      gg:rect(x, y, kw, kh, { line_width = here and 3 or (usedp[l] and 1 or 2) })
      gg:text(x + (kw - kit.width(med, l)) // 2, y + (kh - kit.line_h('medium')) // 2, l, { font = med })
      if usedp[l] and not here then gg:line(x + 6, y + kh - 7, x + kw - 6, y + kh - 7) end
    end
    for k, b in ipairs(BUTTONS) do
      local x, y, bw, bh = button_rect(k)
      kit.button(gg, x, y, bw, bh, b)
    end
    if ERR then gg:text(12, H - 30, kit.short('ERR ' .. ERR, 48), { font = small }) end
  end)
  if not ok then pcall(function() gg:text(8, H - 60, kit.short('draw ERR ' .. tostring(e), 46)) end) end
end

------------------------------------------------------------------ input

local function how_to()
  kit.show({ title = 'How to play', lines = {
    'Every letter of the quote stands for another letter, the same one all through. Tap a letter, then the key it stands for; Hint shows one, Check strikes out wrong guesses.',
    'Tips: a one-letter word is A or I. THE and AND are the commonest three-letter words. The commonest letters are E, T, A, O, I, N. A letter never stands for itself.',
  }, rows = { { { 'Close', kit.close } } }, cancel = kit.close })
end

local function restart()
  guess, hinted, wrong, checks, solved, msg = {}, {}, {}, 0, false, nil
  cursor = next_open(0)
  save()
end

local function menu()
  local rows = {
    { { 'Today', function() kit.close(); save(); open_day(today) end, pday ~= today },
      { 'Earlier', function() kit.close(); save(); open_day(pday - 1) end } },
    { { 'Later', function() kit.close(); save(); open_day(pday + 1) end, pday < today },
      { 'Start over', function() kit.close(); restart() end } },
    { { 'How to play', how_to }, { 'Close', kit.close } },
  }
  kit.show({ title = 'Cryptogram', lines = { date_label(pday) .. ', quote ' .. puz.no .. ' of ' .. (count or 0) .. '.' },
             rows = rows, cancel = kit.close })
end

local function in_rect(x, y, rx, ry, rw, rh) return x >= rx and x < rx + rw and y >= ry and y < ry + rh end

local function tap(x, y)
  if kit.tap_modal(x, y) then return end
  if not puz then return end
  for k = 1, 4 do
    local bx, by, bw, bh = button_rect(k)
    if in_rect(x, y, bx, by, bw, bh) then
      if k == 1 then hint() elseif k == 2 then check() elseif k == 3 then erase() else menu() end
      return
    end
  end
  for k = 1, 26 do
    local kx, ky, kw, kh = key_rect(k)
    if in_rect(x, y, kx - KEY_GAP // 2, ky - KEY_GAP // 2, kw + KEY_GAP, kh + KEY_GAP) then assign(ALPHA:sub(k, k)); return end
  end
  if y >= QUOTE_Y - 6 and y < QUOTE_BOTTOM then
    for i, cl in ipairs(cells) do
      if cl.c and in_rect(x, y, cl.x, cl.y - 6, char_w(cl.ch), RH) then
        cursor = i
        if not solved then msg = nil end
        return
      end
    end
  end
end

local function move(d)
  if not cursor then cursor = next_open(0) or 1; return end
  local n = #cells
  for k = 1, n do
    local i = (cursor - 1 + d * k) % n + 1
    if cells[i].c then cursor = i; return end
  end
end

function on_input(c, ev)
  ERR = nil
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then
      tap(ev.x or 0, ev.y or 0)
    elseif ev.type == 'key' and kit.key_accepted(ev) then
      if kit.modal() then
        if ev.key == 'back' and kit.modal().cancel then kit.modal().cancel() end
      elseif ev.key == 'down' or ev.key == 'right' then move(1)
      elseif ev.key == 'up' or ev.key == 'left' then move(-1) end
    end
  end)
  if not ok then ERR = tostring(e) end
  kit.refresh()
  return true
end

function on_load(c)
  local ok, e = pcall(function()
    load_saved()
    today = local_day()
    open_day(today)
  end)
  if not ok then ERR = tostring(e) end
end
function on_leave() pcall(save) end

if rawget(_G, '__TEST') then
  __TEST.api = { puz = function() return puz end, cells = function() return cells end, guess = function() return guess end,
                 cursor = function() return cursor end, msg = function() return msg end, solved = function() return solved end,
                 wrong = function() return wrong end, hinted = function() return hinted end, key_rect = key_rect,
                 open_day = open_day, pday = function() return pday end, START = START, make_cipher = make_cipher,
                 count = function() return count end, date_label = date_label }
end
